<script setup>import{onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{showSuccessToast}from'vant';import{api}from'../api/crm';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),canTransfer=['ADMIN','SALES_MANAGER'].includes(auth.user?.role);const id=Number(useRoute().params.id),customer=ref(null),contacts=ref([]),followUps=ref([]),opportunities=ref([]),active=ref('follow'),popup=ref('');const contact=reactive({customerId:id,name:'',title:'',phone:'',email:'',primaryContact:true,notes:''});const follow=reactive({customerId:id,opportunityId:null,method:'WECHAT',content:'',followUpAt:'',nextAction:'',nextFollowUpDate:''});const opportunity=reactive({customerId:id,name:'',amount:0,stage:'LEAD',probability:10,expectedCloseDate:'',nextStep:''});const methods={PHONE:'电话',WECHAT:'微信',VISIT:'拜访',EMAIL:'邮件',OTHER:'其他'},stages={LEAD:'初步接触',DISCOVERY:'需求确认',PROPOSAL:'方案报价',NEGOTIATION:'商务谈判',WON:'赢单',LOST:'输单'};const statusLabels={LEAD:'潜在线索',FOLLOWING:'持续跟进',CUSTOMER:'成交客户',INACTIVE:'暂不跟进'};async function load(){[customer.value,contacts.value,followUps.value,opportunities.value]=await Promise.all([api.customer(id),api.contacts(id),api.followUps(id),api.opportunities(id)])}async function addContact(){await api.createContact(contact);popup.value='';showSuccessToast('联系人已添加');load()}async function addFollow(){await api.createFollowUp({...follow,opportunityId:follow.opportunityId||null,followUpAt:follow.followUpAt||null,nextFollowUpDate:follow.nextFollowUpDate||null});popup.value='';showSuccessToast('跟进已记录');load()}async function addOpportunity(){await api.createOpportunity({...opportunity,amount:Number(opportunity.amount),probability:Number(opportunity.probability),expectedCloseDate:opportunity.expectedCloseDate||null});popup.value='';showSuccessToast('商机已创建');load()}onMounted(load)</script>
<template><div class="page safe-top"><van-nav-bar title="客户详情" left-arrow @click-left="$router.back()"/><template v-if="customer"><section class="summary brand-gradient"><div class="top"><span class="badge">{{customer.level}}级</span><span>{{statusLabels[customer.status]||'客户'}}</span></div><h1>{{customer.shortName||customer.name}}</h1><p>{{customer.name}}</p><div class="owner">负责人 {{customer.ownerName}} · {{customer.industry||'行业未设置'}}</div><button v-if="canTransfer" class="transfer-link" @click="$router.push(`/customers/${id}/transfer`)">调整负责人</button></section><section class="card info-card"><van-cell title="联系电话" :value="customer.phone||'未设置'" icon="phone-o" :url="customer.phone?`tel:${customer.phone}`:''"/><van-cell title="下次跟进" :value="customer.nextFollowUpDate||'未安排'" icon="underway-o"/><van-cell title="客户来源" :value="customer.source||'未设置'" icon="aim"/></section><div class="actions"><button @click="popup='contact'"><van-icon name="contact-o"/>联系人</button><button @click="popup='follow'"><van-icon name="chat-o"/>写跟进</button><button @click="popup='opportunity'"><van-icon name="chart-trending-o"/>建商机</button></div><van-tabs v-model:active="active" background="transparent" color="#2856a8"><van-tab title="跟进动态" name="follow"><section v-for="item in followUps" :key="item.id" class="card timeline"><i></i><div><div class="head"><b>{{methods[item.method]}}跟进</b><span>{{item.followUpAt?.replace('T',' ').slice(0,16)}}</span></div><p>{{item.content}}</p><div v-if="item.nextAction" class="next">下一步：{{item.nextAction}}</div></div></section><div v-if="!followUps.length" class="empty">暂无跟进记录</div></van-tab><van-tab :title="`联系人 ${contacts.length}`" name="contacts"><section v-for="item in contacts" :key="item.id" class="card contact"><div class="avatar">{{item.name.slice(0,1)}}</div><div><b>{{item.name}} <span v-if="item.primaryContact" class="tag">主要</span></b><p class="muted">{{item.title||'未设置职位'}} · {{item.phone||'暂无电话'}}</p></div><a v-if="item.phone" :href="`tel:${item.phone}`"><van-icon name="phone-o"/></a></section></van-tab><van-tab :title="`商机 ${opportunities.length}`" name="opps"><section v-for="item in opportunities" :key="item.id" class="card"><div class="head"><b>{{item.name}}</b><span class="tag">{{stages[item.stage]}}</span></div><div class="amount">¥ {{Number(item.amount).toLocaleString()}}</div><div class="muted">成交概率 {{item.probability}}% · {{item.expectedCloseDate||'未定日期'}}</div></section></van-tab></van-tabs></template><van-popup :show="!!popup" position="bottom" round @click-overlay="popup=''" :style="{maxHeight:'86%'}"><div v-if="popup==='contact'" class="form"><h2>添加联系人</h2><van-field v-model="contact.name" label="姓名" required/><van-field v-model="contact.title" label="职位"/><van-field v-model="contact.phone" label="手机" type="tel"/><van-field v-model="contact.email" label="邮箱"/><van-cell title="设为主要联系人"><template #right-icon><van-switch v-model="contact.primaryContact" size="24px"/></template></van-cell><van-field v-model="contact.notes" label="备注" type="textarea"/><button class="action-btn" :disabled="!contact.name" @click="addContact">保存联系人</button></div><div v-else-if="popup==='follow'" class="form"><h2>记录客户跟进</h2><div class="inline-label">跟进方式</div><van-radio-group v-model="follow.method" direction="horizontal"><van-radio name="PHONE">电话</van-radio><van-radio name="WECHAT">微信</van-radio><van-radio name="VISIT">拜访</van-radio><van-radio name="EMAIL">邮件</van-radio></van-radio-group><van-field v-model="follow.content" label="跟进内容" required type="textarea" rows="3"/><van-field v-model="follow.nextAction" label="下一步计划" type="textarea" rows="2"/><van-field v-model="follow.nextFollowUpDate" label="下次跟进" type="date"/><button class="action-btn" :disabled="!follow.content" @click="addFollow">保存跟进</button></div><div v-else class="form"><h2>创建销售商机</h2><van-field v-model="opportunity.name" label="商机名称" required/><van-field v-model="opportunity.amount" label="预计金额" type="number"/><van-field v-model="opportunity.expectedCloseDate" label="预计成交" type="date"/><van-field v-model="opportunity.nextStep" label="下一步" type="textarea"/><button class="action-btn" :disabled="!opportunity.name" @click="addOpportunity">保存商机</button></div></van-popup></div></template>
<style scoped>.van-nav-bar{background:transparent;margin:-8px -16px 14px}.summary{border-radius:22px;padding:22px}.summary .top{display:flex;gap:10px;font-size:12px;opacity:.82}.badge{background:#ffffff26;padding:3px 8px;border-radius:8px}.summary h1{font-size:23px;margin:17px 0 5px}.summary p{font-size:12px;opacity:.72;margin:0}.owner{margin-top:18px;font-size:12px;opacity:.8}.info-card{padding:5px;margin-top:14px}.actions{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:16px 0}.actions button{border:0;background:#fff;border-radius:14px;height:52px;color:#2856a8}.actions .van-icon{margin-right:5px}.timeline{display:grid;grid-template-columns:9px 1fr;gap:12px}.timeline i{width:9px;height:9px;border-radius:50%;background:#2856a8;margin-top:5px}.head{display:flex;justify-content:space-between;gap:10px}.head span{font-size:11px;color:#929dad}.timeline p{color:#48586e;line-height:1.6;margin:9px 0}.next{background:#f1f4f9;border-radius:9px;padding:8px;font-size:12px;color:#66758a}.contact{display:flex;align-items:center;gap:12px}.avatar{width:42px;height:42px;border-radius:13px;background:#e9eef8;color:#2856a8;display:grid;place-items:center;font-weight:700}.contact div:nth-child(2){flex:1}.contact p{margin:6px 0 0}.contact a{font-size:22px;color:#2856a8}.amount{font-size:21px;font-weight:750;color:#2856a8;margin:14px 0 6px}.form{padding:18px 20px 32px;overflow:auto}.form h2{margin:0 0 12px}.inline-label{font-size:14px;color:#646b75;padding:12px 16px}.van-radio-group{padding:0 16px 14px;gap:13px}.action-btn{margin-top:14px}.transfer-link{margin-top:12px;padding:0;border:0;background:transparent;color:#fff;text-decoration:underline;font-size:12px}</style>
